import requests

class EthereumBytecodeConverter:
    """
    A class to convert Ethereum transaction bytecode to opcode using Etherscan's API.
    """

    def __init__(self, api_key):
        """
        Initializes the converter with the provided Etherscan API key.

        :param api_key: str - Your Etherscan API key.
        """
        self.api_key = api_key
        self.base_url = "https://api.etherscan.io/api"

    def bytecode_to_opcode(self, bytecode):
        """
        Converts Ethereum bytecode to opcode using Etherscan's Bytecode to Opcode tool.

        :param bytecode: str - The Ethereum bytecode to convert.
        :return: dict - The response from the Etherscan API containing the opcode.
        """
        # Validate input
        if not isinstance(bytecode, str) or not bytecode.startswith('0x'):
            raise ValueError("Bytecode must be a hexadecimal string starting with '0x'.")

        # Prepare the API request parameters
        params = {
            'module': 'proxy',
            'action': 'eth_getOpcode',
            'bytecode': bytecode,
            'apikey': self.api_key
        }

        try:
            # Make the API request
            response = requests.get(self.base_url, params=params)
            response.raise_for_status()  # Raise an error for bad responses

            # Parse the JSON response
            data = response.json()

            # Check for errors in the response
            if data['status'] != '1':
                raise Exception(f"Error from Etherscan API: {data['message']}")

            return data['result']

        except requests.exceptions.RequestException as e:
            raise Exception(f"HTTP Request failed: {e}")
        except Exception as e:
            raise Exception(f"An error occurred: {e}")

